def calcular_media(notas: list[float]) -> float:
    if not notas:
        return 0.0
    return sum(notas) / len(notas)


def classificar_aluno(media: float, minimo: float = 7.0) -> str:
    return 'Aprovado' if media >= minimo else 'Em recuperação'


media_final = calcular_media([8.0, 7.5, 9.0])
print(f'{media_final:.2f} -> {classificar_aluno(media_final)}')
